public void Refresh(RefreshMask mask = RefreshMask.All)
{
    // Mesh
    if ((mask & RefreshMask.UV) > 0)
        RefreshUV(facesInternal);

    if ((mask & RefreshMask.Colors) > 0)
        RefreshColors();

    if ((mask & RefreshMask.Normals) > 0)
        RefreshNormals();

    if ((mask & RefreshMask.Tangents) > 0)
        RefreshTangents();

    if ((mask & RefreshMask.Collisions) > 0)
        EnsureMeshColliderIsAssigned();

    if ((mask & RefreshMask.Bounds) > 0 && mesh != null)
        mesh.RecalculateBounds();

    IncrementVersionIndex();
}

void CacheSelection()
{
    if (m_SelectedCacheDirty)
    {
        m_SelectedCacheDirty = false;
        m_SelectedSharedVertices.Clear();
        m_SelectedCoincidentVertices.Clear();
        var lookup = sharedVertexLookup;
        m_SelectedSharedVerticesCount = 0;
        m_SelectedCoincidentVertexCount = 0;

        try
        {
            foreach (var i in m_SelectedVertices)
            {
                if (m_SelectedSharedVertices.Add(lookup[i]))
                {
                    var coincident = sharedVerticesInternal[lookup[i]];

                    m_SelectedSharedVerticesCount++;
                    m_SelectedCoincidentVertexCount += coincident.Count;

                    m_SelectedCoincidentVertices.AddRange(coincident);
                }
            }
        }
        catch
        {
            ClearSelection();
        }
    }
}

/// <summary>
/// Ensures that the UnityEngine.Mesh associated with this object is unique. When instantiating a ProBuilderMesh,
/// the mesh asset will reference the original instance. If you are making a copy to edit, you must call
/// MakeUnique to avoid modifying a shared mesh asset.
/// </summary>
public void MakeUnique()
{
    mesh = mesh != null
        ? Instantiate(mesh)
        : new Mesh();
    mesh.name = $"pb_Mesh{this.GetObjectId()}";

    if (meshSyncState == MeshSyncState.InSync)
    {
        filter.mesh = mesh;
        return;
    }

    ToMesh();
    Refresh();
}
